-- Local rollback-only security tests. Raw credentials stay in temporary state.
begin;
set local search_path=public,extensions,pg_catalog;
select no_plan();
select has_function('public','connect_code_generate',array[]::text[],'Connect generation RPC exists');
create temp table connect_test(label text primary key,data jsonb);
grant select,insert,update on connect_test to authenticated;
insert into auth.users(id,email,email_confirmed_at) values
 ('81000000-0000-4000-8000-000000000001','connect-admin@example.invalid',now()),
 ('81000000-0000-4000-8000-000000000002','connect-target@example.invalid',now()),
 ('81000000-0000-4000-8000-000000000003','connect-other@example.invalid',now()),
 ('81000000-0000-4000-8000-000000000004','connect-foreign-admin@example.invalid',now());
select set_config('request.jwt.claims','{"sub":"81000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
insert into wedding_private.weddings(id,owner_user_id,title,city,budget_ceiling_paise) values
 ('82000000-0000-4000-8000-000000000001','81000000-0000-4000-8000-000000000001','Connect synthetic wedding','Test city',100000);
select set_config('request.jwt.claims','{"sub":"81000000-0000-4000-8000-000000000004","role":"authenticated"}',true);
insert into wedding_private.weddings(id,owner_user_id,title,city,budget_ceiling_paise) values
 ('82000000-0000-4000-8000-000000000002','81000000-0000-4000-8000-000000000004','Foreign synthetic wedding','Test city',100000);
select ok(not has_table_privilege('authenticated','wedding_access.connect_codes','SELECT,INSERT,UPDATE,DELETE'),'Clients have no direct code/hash privileges');
select ok(not has_table_privilege('authenticated','wedding_access.connect_attempts','SELECT,INSERT,UPDATE,DELETE'),'Clients cannot reset attempt counters');
select ok(not pg_has_role('authenticated','wedding_connect_writer','MEMBER'),'Clients cannot assume code helper role');
select ok(not rolcanlogin and not rolbypassrls and not rolsuper,'Code helper has no login or RLS bypass') from pg_roles where rolname='wedding_connect_writer';
select ok(not has_schema_privilege('wedding_connect_writer','auth','USAGE'),'No managed Auth access required');
select ok(bool_and(relrowsecurity and relforcerowsecurity),'Both private tables enforce forced RLS') from pg_class where oid in ('wedding_access.connect_codes'::regclass,'wedding_access.connect_attempts'::regclass);
select ok(not has_function_privilege('authenticated','wedding_access.connect_attempt(text)','EXECUTE'),'Client cannot directly call internal limiter');
set local role anon;
select throws_ok($$select public.connect_code_generate()$$,'42501',null,'Anonymous generation denied');
select throws_ok($$select public.connect_code_revoke()$$,'42501',null,'Anonymous revocation denied');
select throws_ok($$select public.invitation_issue_connect('82000000-0000-4000-8000-000000000001',repeat('a',64))$$,'42501',null,'Anonymous redemption denied');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"81000000-0000-4000-8000-000000000002","role":"authenticated","is_anonymous":true}',true);
select throws_ok($$select public.connect_code_generate()$$,'42501',null,'Anonymous Auth identity denied');
select set_config('request.jwt.claims','{"sub":"81000000-0000-4000-8000-000000000002","role":"authenticated"}',true);
insert into connect_test values('old',public.connect_code_generate()),('current',public.connect_code_generate());
select ok((select data->>'code' ~ '^[a-f0-9]{64}$' from connect_test where label='current'),'High-entropy code format');
select ok((select (data->>'expires_at')::timestamptz between clock_timestamp()+interval '14 minutes' and clock_timestamp()+interval '16 minutes' from connect_test where label='current'),'Code expires in fifteen minutes');
select ok((select data from connect_test where label='old')<>(select data from connect_test where label='current'),'Replacement generates fresh credential');
select throws_ok($$select code_hash from wedding_access.connect_codes$$,'42501',null,'Even recipient cannot read stored hashes');
reset role;
select is((select count(*) from wedding_access.connect_codes where user_id='81000000-0000-4000-8000-000000000002'),1::bigint,'Only one credential row per recipient');
select ok((select c.code_hash=encode(sha256(convert_to(t.data->>'code','UTF8')),'hex') and c.code_hash<>t.data->>'code' from wedding_access.connect_codes c,connect_test t where t.label='current' and c.user_id='81000000-0000-4000-8000-000000000002'),'Only SHA256 hash persisted');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"81000000-0000-4000-8000-000000000003","role":"authenticated","user_metadata":{"role":"Admin"}}',true);
select throws_ok($$select public.invitation_issue_connect('82000000-0000-4000-8000-000000000001',(select data->>'code' from connect_test where label='current'))$$,'42501',null,'Unrelated user cannot redeem with forged metadata');
select public.connect_code_revoke();
select set_config('request.jwt.claims','{"sub":"81000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select throws_ok($$select public.invitation_issue_connect('82000000-0000-4000-8000-000000000002',(select data->>'code' from connect_test where label='current'))$$,'42501',null,'Owner cannot redeem against another wedding');
select is(public.invitation_issue_connect('82000000-0000-4000-8000-000000000001',(select data->>'code' from connect_test where label='old'))->>'error','NOT_FOUND','Replaced code rejected');
insert into connect_test values('invitation',public.invitation_issue_connect('82000000-0000-4000-8000-000000000001',(select data->>'code' from connect_test where label='current')));
select ok((select data ? 'token' and not data ? 'recipient_user_id' and not data ? 'code_hash' from connect_test where label='invitation'),'Admin gets invitation, not directory lookup');
reset role;
select is((select count(*) from wedding_access.memberships where wedding_id='82000000-0000-4000-8000-000000000001'),0::bigint,'Redemption alone never creates membership');
select is((select recipient_user_id from wedding_access.invitations where wedding_id='82000000-0000-4000-8000-000000000001'),'81000000-0000-4000-8000-000000000002'::uuid,'Invitation binds code owner UUID');
select ok((select consumed_at is not null from wedding_access.connect_codes where user_id='81000000-0000-4000-8000-000000000002'),'Successful issuance consumes code');
set local role authenticated;
select is(public.invitation_issue_connect('82000000-0000-4000-8000-000000000001',(select data->>'code' from connect_test where label='current'))->>'error','NOT_FOUND','Replayed code rejected');
select set_config('request.jwt.claims','{"sub":"81000000-0000-4000-8000-000000000003","role":"authenticated"}',true);
select throws_ok($$select public.invitation_accept((select data->>'token' from connect_test where label='invitation'))$$,'42501',null,'Code bridge cannot authorize wrong recipient');
select set_config('request.jwt.claims','{"sub":"81000000-0000-4000-8000-000000000002","role":"authenticated"}',true);
select is(public.invitation_accept((select data->>'token' from connect_test where label='invitation')),'82000000-0000-4000-8000-000000000001'::uuid,'Existing acceptance remains mandatory and succeeds');
select ok(public.planning_read('82000000-0000-4000-8000-000000000001') is not null,'Accepted Member reads planning');
select is(public.finance_read('82000000-0000-4000-8000-000000000001'),null::jsonb,'Member finance denied');
select throws_ok($$select public.invitation_issue_connect('82000000-0000-4000-8000-000000000001',repeat('a',64))$$,'42501',null,'Member cannot redeem');
insert into connect_test values('member',public.connect_code_generate());
select set_config('request.jwt.claims','{"sub":"81000000-0000-4000-8000-000000000003","role":"authenticated"}',true);
insert into connect_test values('expired',public.connect_code_generate());
reset role;
update wedding_access.connect_codes set expires_at=clock_timestamp()-interval '1 second' where user_id='81000000-0000-4000-8000-000000000003';
update wedding_access.connect_attempts set window_started=clock_timestamp()-interval '11 minutes' where operation='redeem' and user_id='81000000-0000-4000-8000-000000000001';
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"81000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select is(public.invitation_issue_connect('82000000-0000-4000-8000-000000000001',(select data->>'code' from connect_test where label='expired'))->>'error','NOT_FOUND','Expired code rejected');
select is(public.invitation_issue_connect('82000000-0000-4000-8000-000000000001',(select data->>'code' from connect_test where label='member'))->>'error','CONFLICT','Existing membership cannot be duplicated');
reset role;
select ok((select consumed_at is null from wedding_access.connect_codes where user_id='81000000-0000-4000-8000-000000000002'),'Issuance conflict does not consume code');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"81000000-0000-4000-8000-000000000003","role":"authenticated"}',true);
insert into connect_test values('revoked',public.connect_code_generate());
select public.connect_code_revoke();
select set_config('request.jwt.claims','{"sub":"81000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select is(public.invitation_issue_connect('82000000-0000-4000-8000-000000000001',(select data->>'code' from connect_test where label='revoked'))->>'error','NOT_FOUND','Self-revoked code rejected');
insert into connect_test values('self',public.connect_code_generate());
select is(public.invitation_issue_connect('82000000-0000-4000-8000-000000000001',(select data->>'code' from connect_test where label='self'))->>'error','NOT_FOUND','Self invitation cannot create Admin');
select is(public.invitation_issue_connect('82000000-0000-4000-8000-000000000001','bad')->>'error','NOT_FOUND','Malformed direct RPC guess rejected and counted');
select is(public.invitation_issue_connect('82000000-0000-4000-8000-000000000001',repeat('f',64))->>'error','RATE_LIMITED','Sixth attempt denied by actor-scoped counter');
reset role;
select is((select attempts from wedding_access.connect_attempts where user_id='81000000-0000-4000-8000-000000000001' and operation='redeem'),5,'Failures retain five counted attempts');
update wedding_access.connect_attempts set window_started=clock_timestamp()-interval '11 minutes' where user_id='81000000-0000-4000-8000-000000000001' and operation='redeem';
set local role authenticated;
select is(public.invitation_issue_connect('82000000-0000-4000-8000-000000000001',null)->>'error','NOT_FOUND','Window expiry permits a new counted attempt');
reset role;
select is((select attempts from wedding_access.connect_attempts where user_id='81000000-0000-4000-8000-000000000001' and operation='redeem'),1,'Window resets safely');
update wedding_access.connect_attempts set window_started=clock_timestamp()-interval '11 minutes' where operation='generate' and user_id in ('81000000-0000-4000-8000-000000000001','81000000-0000-4000-8000-000000000002','81000000-0000-4000-8000-000000000003');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"81000000-0000-4000-8000-000000000003","role":"authenticated"}',true);
do $$begin for i in 1..5 loop perform public.connect_code_generate();end loop;end$$;
select is(public.connect_code_generate()->>'error','RATE_LIMITED','Code generation also bounded to five per window');
reset role;
select is((select count(*) from wedding_access.connect_codes where user_id='81000000-0000-4000-8000-000000000003'),1::bigint,'Repeated generation cannot grow credential storage');
select is((select owner_user_id from wedding_private.weddings where id='82000000-0000-4000-8000-000000000001'),'81000000-0000-4000-8000-000000000001'::uuid,'Owner identity unchanged');
select is((select count(*) from wedding_access.memberships where wedding_id='82000000-0000-4000-8000-000000000001'),1::bigint,'Only explicit invitation acceptance created one Member');
select * from finish();
rollback;
